"""Calendar-aware dispatch over the existing durable queues and workspace store.

No new scheduler, paid request, trade permission or broker client lives here.
Opening the status endpoint only reads persisted evidence. Explicit refreshes
remain independent of the automatic price-polling calendar.
"""
from __future__ import annotations

from contextlib import closing
from datetime import datetime, timezone
import json
from typing import Any

from fastapi import HTTPException

try:
    from . import app as backend, volume_state as state, volume_jobs as jobs
    from . import market_schedule
    from .ai_budget import transaction
    from .ai_jobs import AnalysisQueue
except ImportError:
    import app as backend
    import volume_state as state
    import volume_jobs as jobs
    import market_schedule
    from ai_budget import transaction
    from ai_jobs import AnalysisQueue

EVENT_INTERVAL = 600
PRICE_INTERVAL = 300
EVENT_PREFIX = "auto.events."
ANALYSIS_ORIGIN = "dispatch_analysis"


def _controller():
    try:
        from . import autonomous_controller
    except ImportError:
        import autonomous_controller
    return autonomous_controller


def _age(value: str | None, now: datetime) -> float | None:
    try:
        age = (now - market_schedule.instant(value)).total_seconds()
        return age if age >= 0 else None
    except (ValueError, TypeError, OverflowError):
        return None


def schedule(user: Any, *, now: datetime | None = None, snapshot: dict | None = None) -> dict:
    clock = now or datetime.now(timezone.utc)
    if snapshot is None:
        snapshot = state.saved_snapshot(user, _controller()._currency(int(user["id"])))
    result = market_schedule.polling_state((snapshot or {}).get("calendar"),
        market_schedule.required_exchanges(snapshot), now=clock)
    events = (snapshot or {}).get("event_monitor", {})
    age = _age(events.get("checked_at"), clock)
    result.update(event_monitoring_independent_of_market=True,
                  events=events, event_interval_seconds=EVENT_INTERVAL,
                  price_interval_seconds=PRICE_INTERVAL,
                  events_due_in_seconds=0 if age is None else max(0, int(EVENT_INTERVAL - age)),
                  last_valuation_at=(snapshot or {}).get("as_of"),
                  bootstrap_required=snapshot is None)
    return result


class _PendingEvents(Exception):
    def __init__(self, job_id: str):
        self.job_id = job_id


def enqueue_events(user: Any, *, now: datetime | None = None) -> dict:
    clock = now or datetime.now(timezone.utc)
    user_id = int(user["id"])
    current = _controller()._user(user_id)
    if current is None or not current["tinvest_token_encrypted"]:
        return {"state": "not_connected"}
    if not _controller().preferences(user_id)["enabled"]:
        return {"state": "paused"}
    currency = _controller()._currency(user_id)
    snapshot = state.saved_snapshot(current, currency)
    if snapshot is None:
        return {"state": "awaiting_first_snapshot"}
    age = _age(snapshot.get("event_monitor", {}).get("checked_at"), clock)
    if age is not None and age < EVENT_INTERVAL:
        return {"state": "current"}
    key = state.broker_key(current)
    prefix = EVENT_PREFIX + key + "." + currency + "."
    checkpoint = {"broker_key": key}
    with closing(backend.connect()) as db:
        last = db.execute("""SELECT checkpoint_json FROM workspace_jobs WHERE user_id=? AND request_id LIKE ?
            AND state='failed' AND updated_at>? ORDER BY updated_at DESC,id DESC LIMIT 1""",
            (user_id, prefix + "%", int(clock.timestamp()) - 86400)).fetchone()
    if last is not None:
        prior = json.loads(last[0])
        if prior.get("broker_key") == key:
            checkpoint = prior

    def before_insert(db, _):
        _controller().assert_enabled_in(db, user_id)
        owner = db.execute("SELECT tinvest_token_encrypted FROM users WHERE id=?", (user_id,)).fetchone()
        if owner is None or state.broker_key(owner) != key:
            raise HTTPException(409, "monitoring_connection_changed")
        pending = db.execute("""SELECT id FROM workspace_jobs WHERE user_id=? AND request_id LIKE ?
            AND state IN ('queued','running') AND cancel_requested=0 ORDER BY created_at,id LIMIT 1""",
            (user_id, prefix + "%")).fetchone()
        if pending:
            raise _PendingEvents(pending["id"])

    try:
        return jobs.enqueue(user_id, prefix + str(int(clock.timestamp()) // EVENT_INTERVAL), "events",
            {"currency": currency}, before_insert=before_insert, checkpoint=checkpoint)
    except _PendingEvents as pending:
        return {"state": "coalesced", "job_id": pending.job_id}


def _enqueue_analysis(user: Any, *, automatic: bool, now: datetime) -> dict:
    user_id, key = int(user["id"]), state.broker_key(user)
    with transaction(backend.connect) as db:
        _controller().assert_enabled_in(db, user_id)
        owner = db.execute("SELECT tinvest_token_encrypted FROM users WHERE id=?", (user_id,)).fetchone()
        if owner is None or state.broker_key(owner) != key or key == "disconnected":
            raise HTTPException(409, "monitoring_connection_changed")
        result = AnalysisQueue(backend.connect).enqueue_in(db, user_id, now=int(now.timestamp()))
        if not automatic:
            mark_manual_in(db, user_id, result["job_id"])
        elif not result["coalesced"]:
            state.record(db, user_id, ANALYSIS_ORIGIN, result["job_id"],
                         {"automatic": True, "broker_key": key, "queued_at": now.isoformat()})
        db.execute("""DELETE FROM workspace_records WHERE user_id=? AND kind=? AND updated_at<?
            AND id NOT IN (SELECT id FROM ai_work_jobs WHERE status IN ('queued','running'))""",
            (user_id, ANALYSIS_ORIGIN, int(now.timestamp()) - 7 * 86400))
    return result


def mark_manual_in(db, user_id: int, job_id: str) -> None:
    # If a manual request coalesces with an automatic job, its explicit intent
    # must still permit a read-only check outside the scheduled window.
    db.execute("DELETE FROM workspace_records WHERE user_id=? AND kind=? AND id=?",
               (user_id, ANALYSIS_ORIGIN, job_id))


def enqueue_manual_analysis(user: Any) -> dict:
    return _enqueue_analysis(user, automatic=False, now=datetime.now(timezone.utc))


def automatic_collection_gate(user: Any, payload: dict, checkpoint: dict) -> dict | None:
    if checkpoint.get("broker_key") not in {None, state.broker_key(user)}:
        raise HTTPException(409, "workspace_broker_connection_changed")
    _controller().assert_enabled(int(user["id"]))
    snapshot = state.saved_snapshot(user, payload.get("currency", "RUB"))
    # A first read is necessary to learn which instruments/calendars are needed.
    if snapshot is None:
        return None
    current = schedule(user, snapshot=snapshot)
    if current["regular_price_polling_allowed"]:
        return None
    return {"state": "waiting", "reason": current["reason"], "valuation_refreshed": False}


def automatic_analysis_gate(user: Any, job_context: tuple | None, now: datetime) -> dict | None:
    if job_context is None:
        return None
    with closing(backend.connect()) as db:
        row = db.execute("SELECT payload_json FROM workspace_records WHERE user_id=? AND kind=? AND id=?",
            (int(user["id"]), ANALYSIS_ORIGIN, job_context[0])).fetchone()
    if row is None:
        return None
    origin = json.loads(row[0])
    if origin.get("broker_key") != state.broker_key(user):
        raise HTTPException(409, "monitoring_connection_changed")
    current = schedule(user, now=now)
    return None if current["regular_price_polling_allowed"] else current


def enqueue_cycle(user: Any, *, now: datetime | None = None) -> dict:
    """A cheap persisted-data decision. A failed lane cannot starve another."""
    clock = now or datetime.now(timezone.utc)
    current = _controller()._user(int(user["id"]))
    if current is None or not current["tinvest_token_encrypted"]:
        return {"state": "not_connected"}
    if not _controller().preferences(int(user["id"]))["enabled"]:
        return {"state": "paused"}
    snapshot = state.saved_snapshot(current, _controller()._currency(int(user["id"])))
    window = schedule(current, now=clock, snapshot=snapshot)
    result = {"state": "scheduled", "market": window["state"], "lanes": {}}
    actions = [("events", lambda: enqueue_events(current, now=clock))]
    if snapshot is None or window["regular_price_polling_allowed"]:
        actions.append(("collection", lambda: _controller().enqueue_collection(current, now=clock.timestamp())))
    observed_age = _age((snapshot or {}).get("as_of"), clock)
    if snapshot is not None and window["regular_price_polling_allowed"] and (observed_age is None or observed_age >= PRICE_INTERVAL):
        actions.append(("analysis", lambda: _enqueue_analysis(current, automatic=True, now=clock)))
    for name, action in actions:
        try:
            result["lanes"][name] = action()
        except HTTPException as error:
            result["lanes"][name] = {"state": "deferred", "http_status": error.status_code}
    return result

"""Resumable event-only collection without refreshing prices or valuation time."""
from __future__ import annotations

from copy import deepcopy
from datetime import datetime, timedelta, timezone
from typing import Any

from fastapi import HTTPException

try:
    from . import volume_state as state, volume_workspace as workspace
    from . import autonomous_controller as controller
    from .volume_contract import digest, now_iso
    from .market_schedule import instant
except ImportError:
    import volume_state as state
    import volume_workspace as workspace
    import autonomous_controller as controller
    from volume_contract import digest, now_iso
    from market_schedule import instant


def _basis(snapshot: dict) -> str:
    return digest({"currency": snapshot.get("currency"),
        "accounts": sorted(row["id"] for row in snapshot.get("accounts", [])),
        "holdings": sorted((row["account_id"], row["instrument_uid"], row.get("quantity"))
                           for row in snapshot.get("positions", []))})


def _sources(snapshot: dict, extra: list) -> list:
    # Keep provenance still referenced by retained attribution/positions, while
    # avoiding an ever-growing list of superseded news/calendar observations.
    needed, stack = set(), [value for key, value in snapshot.items() if key != "sources"]
    while stack:
        value = stack.pop()
        if isinstance(value, dict):
            needed.update(item for item in value.get("source_ids", []) if isinstance(item, str))
            if isinstance(value.get("id"), str) and "method" in value and "provider" in value:
                needed.add(value["id"])
            stack.extend(value.values())
        elif isinstance(value, list):
            stack.extend(value)
    retained = [ref for ref in snapshot.get("sources", []) if ref.get("id") in needed
                or ref.get("method") in {"GetPortfolio", "GetPortfolio/GetPositions"}]
    return list({ref["id"]: ref for ref in retained + extra}.values())


def collect_events(user: Any, payload: dict, checkpoint: dict, progress) -> dict:
    key, currency = state.broker_key(user), payload.get("currency", "RUB")
    if checkpoint.get("broker_key") not in {None, key}:
        raise HTTPException(409, "workspace_broker_connection_changed")
    controller.assert_enabled(int(user["id"]))
    old = state.saved_snapshot(user, currency)
    if old is None:
        raise HTTPException(409, "workspace_refresh_required")
    now = datetime.now(timezone.utc)
    basis = _basis(old)
    try:
        started = instant(checkpoint.get("event_started_at"))
        reusable = 0 <= (now - started).total_seconds() < 86400 and checkpoint.get("event_basis") == basis
    except (TypeError, ValueError):
        reusable = False
    if not reusable:
        checkpoint.clear()
        checkpoint.update(broker_key=key, event_basis=basis, event_started_at=now.isoformat())
    started = instant(checkpoint["event_started_at"])
    for name in ("news", "calendar"):
        previous = checkpoint.get(name)
        if previous is not None:
            try:
                reusable_source = previous.get("state") == "available" and 0 <= (now - instant(previous.get("as_of"))).total_seconds() < 600
            except (TypeError, ValueError):
                reusable_source = False
            if not reusable_source:
                checkpoint.pop(name)
    progress("collecting_events", checkpoint)
    workspace._collect_market_events(user, checkpoint, progress)
    # The event horizon follows the collector clock. It is not the timestamp of
    # the last portfolio valuation and cannot relabel that valuation as current.
    basis_snapshot = {**old, "as_of": started.isoformat()}
    begin = started - timedelta(days=60)
    try:
        previous_start = instant(old.get("operations", {}).get("start"))
        if started - timedelta(days=366) <= previous_start < started:
            begin = previous_start
    except (TypeError, ValueError):
        pass
    checkpoint.setdefault("event_operations_begin", begin.isoformat())
    begin = instant(checkpoint["event_operations_begin"])
    operations, operation_sources, operations_complete = [], [], False
    payouts, payout_sources, payouts_complete = [], [], False
    try:
        operations, operation_sources, operations_complete = workspace._collect_operations(
            user, basis_snapshot, begin, started, checkpoint, progress)
    except HTTPException as error:
        if error.status_code in {401, 403, 409}:
            raise
    try:
        payouts, payout_sources, payouts_complete = workspace._payment_events(user, basis_snapshot, checkpoint, progress)
    except HTTPException as error:
        if error.status_code in {401, 403, 409}:
            raise
    new = deepcopy(old)
    section_times = new.setdefault("section_as_of", {})
    for name in ("attribution", "operations", "payouts", "events"):
        if name in old:
            section_times.setdefault(name, old["as_of"])
    news, calendar = checkpoint["news"], checkpoint["calendar"]
    news_ok = news.get("state") == "available" and news.get("data", {}).get("complete", True) is True
    calendar_ok = calendar.get("state") == "available"
    if news.get("state") in {"available", "partial"}:
        new["news"] = news
        new["events"] = {"items": workspace._held_news(new, news), "complete": news_ok}
        section_times["events"] = news.get("as_of")
    if calendar_ok:
        new["calendar"] = calendar
    if operations_complete:
        new["operations"] = {"items": operations, "complete": True, "start": begin.isoformat(), "end": started.isoformat()}
        section_times["operations"] = started.isoformat()
    actual_operations = new.get("operations", {}).get("items", [])
    if payouts_complete:
        payouts.extend(workspace._received_payout_events(actual_operations))
        new["payouts"] = {"items": sorted(payouts, key=lambda row: str(row.get("date")), reverse=True),
            "complete": operations_complete, "received_range": {"start": new.get("operations", {}).get("start"),
                "end": new.get("operations", {}).get("end")}, "announced_and_received_are_distinct": True,
            "position_basis_at": old["as_of"], "announcements_checked_at": started.isoformat()}
        section_times["payouts"] = started.isoformat()
    checked = now_iso()
    complete = news_ok and calendar_ok and operations_complete and payouts_complete
    new["event_monitor"] = {"checked_at": checked, "complete": complete,
        "collection_started_at": started.isoformat(), "operations_through": started.isoformat(),
        "last_successful_at": checked if complete else old.get("event_monitor", {}).get("last_successful_at"),
        "news": "available" if news_ok else "incomplete", "calendar": "available" if calendar_ok else "unavailable",
        "operations": "available" if operations_complete else "incomplete",
        "payout_announcements": "available" if payouts_complete else "incomplete",
        "reviewed_rating_evidence_rechecked": True, "new_rating_sources_fetched": False,
        "valuation_refreshed": False, "valuation_as_of": old["as_of"], "broker_key": key}
    new["sources"] = _sources(new, operation_sources + payout_sources +
        news.get("sources", []) + calendar.get("sources", []))
    controller.assert_enabled(int(user["id"]))
    progress("persisting_events", checkpoint)
    # The same transaction checks that a concurrent price/manual collector has
    # not replaced any part of the snapshot. A conflict keeps the old result.
    workspace.persist(user, new, expected_snapshot=old)
    if not complete:
        # Persist useful independent lanes, then retain the exact acknowledged
        # cursor in the failed durable job for the next bounded retry.
        progress("events_partial", checkpoint)
        raise HTTPException(503, "event_sources_incomplete")
    return {"snapshot_id": new["snapshot_id"], "currency": currency,
            "as_of": old["as_of"], "event_monitor": new["event_monitor"]}

"""Pure broker-calendar interpretation for read-only polling, never trade permission.

UTC dates and explicit broker windows are authoritative. A weekday, an Android
clock, a cached quote or the deprecated weekend flag cannot open a session.
Free-form interval names are retained as unclassified, not mapped to 'main'.
"""
from __future__ import annotations

from datetime import datetime, timedelta, timezone
from typing import Any

UTC = timezone.utc
MAX_CALENDAR_AGE = 900
MAX_EXCHANGES = 256
MAX_DAYS = 32
MAX_INTERVALS = 128
EXCLUDED_WINDOWS = (
    ("openingAuctionStartTime", "openingAuctionEndTime", "opening_auction"),
    ("closingAuctionStartTime", "closingAuctionEndTime", "closing_auction"),
    ("clearingStartTime", "clearingEndTime", "clearing"),
    ("premarketStartTime", "premarketEndTime", "premarket"),
    ("eveningOpeningAuctionStartTime", "eveningEndTime", "evening"),
    ("eveningStartTime", "eveningEndTime", "evening"),
)


def instant(value: Any) -> datetime:
    if not isinstance(value, str) or not 1 <= len(value) <= 64:
        raise ValueError("calendar_timestamp_invalid")
    parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError("calendar_timestamp_timezone_missing")
    return parsed.astimezone(UTC)


def required_exchanges(snapshot: dict | None) -> tuple[str, ...]:
    # An exact instrument exchange is never silently translated into another
    # section. With no securities yet, the configured universe is MOEX.
    positions = [p for p in (snapshot or {}).get("positions", [])
                 if p.get("instrument_type") in {"share", "bond"}]
    if not positions:
        return ("MOEX",)
    values = []
    for position in positions:
        metadata = position.get("metadata")
        value = metadata.get("exchange") if isinstance(metadata, dict) else None
        if not isinstance(value, str) or not value or len(value) > 100:
            return ()
        values.append(value)
    return tuple(sorted(set(values)))


def _window(row: dict, start: str, end: str) -> tuple[datetime, datetime] | None:
    left, right = row.get(start), row.get(end)
    if left is None and right is None:
        return None
    # A missing boundary cannot turn an auction/clearing into a regular window.
    begin, finish = instant(left), instant(right)
    if not begin < finish or finish - begin > timedelta(days=2):
        raise ValueError("calendar_window_invalid")
    return begin, finish


def _day(row: dict, now: datetime) -> tuple[str, list[datetime], bool]:
    if type(row.get("isTradingDay")) is not bool:
        raise ValueError("calendar_trading_flag_invalid")
    date = instant(row.get("date")).date()
    if not row["isTradingDay"]:
        return ("closed" if date == now.date() else "other_day"), [], False
    window = _window(row, "startTime", "endTime")
    intervals = row.get("intervals", [])
    if not isinstance(intervals, list) or len(intervals) > MAX_INTERVALS:
        raise ValueError("calendar_intervals_invalid")
    # Validate all supplied intervals even though their undocumented vocabulary
    # cannot authorize a session. Malformed additional evidence stays unknown.
    for item in intervals:
        if not isinstance(item, dict) or not isinstance(item.get("type"), str):
            raise ValueError("calendar_interval_invalid")
        span = item.get("interval")
        if not isinstance(span, dict) or _window(span, "startTs", "endTs") is None:
            raise ValueError("calendar_interval_invalid")
    if window is None:
        return ("unknown" if date == now.date() else "other_day"), [], bool(intervals)
    begin, end = window
    if abs((begin.date() - date).days) > 1:
        raise ValueError("calendar_day_window_mismatch")
    boundaries = [t for t in window if t > now]
    state = "scheduled_window" if begin <= now < end else "closed"
    for start_key, end_key, excluded in EXCLUDED_WINDOWS:
        # eveningStart/End is a complete alternative to the optional auction
        # start. Do not demand an auction when the broker did not return one.
        if start_key == "eveningOpeningAuctionStartTime" and row.get(start_key) is None:
            continue
        span = _window(row, start_key, end_key)
        if span is not None:
            boundaries.extend(t for t in span if t > now)
            if span[0] <= now < span[1]:
                state = excluded
    if date != now.date() and not begin <= now < end:
        state = "other_day"
    return state, boundaries, bool(intervals)


def polling_state(calendar: dict | None, exchanges: tuple[str, ...], *, now: datetime) -> dict:
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("aware_calendar_clock_required")
    now = now.astimezone(UTC)
    result = {"state": "unknown", "reason": "calendar_missing", "as_of": None,
              "checked_at": now.isoformat(), "timezone": "UTC", "display_timezone": "Europe/Moscow",
              "required_exchanges": list(exchanges), "next_transition_at": None,
              "regular_price_polling_allowed": False, "main_session_verified": False,
              "trade_permission": False, "interval_classification": "not_available", "sections": []}
    if not exchanges:
        return {**result, "reason": "instrument_exchange_unknown"}
    try:
        envelope = calendar or {}
        if envelope.get("state") != "available":
            return result
        raw = envelope.get("data")
        if not isinstance(raw, dict) or raw.get("timezone") != "UTC":
            raise ValueError("calendar_schema_invalid")
        observed = instant(raw.get("as_of"))
        result["as_of"] = observed.isoformat()
        age = (now - observed).total_seconds()
        if not 0 <= age < MAX_CALENDAR_AGE:
            return {**result, "reason": "calendar_stale_or_future"}
        schedules = raw.get("exchanges")
        if not isinstance(schedules, list) or len(schedules) > MAX_EXCHANGES:
            raise ValueError("calendar_sections_invalid")
        indexed = {}
        for schedule in schedules:
            if not isinstance(schedule, dict) or not isinstance(schedule.get("exchange"), str):
                raise ValueError("calendar_section_invalid")
            name = schedule["exchange"]
            if name in indexed:
                raise ValueError("calendar_section_conflict")
            indexed[name] = schedule
        states, transitions, unclassified = [], [], False
        for name in exchanges:
            schedule = indexed.get(name)
            if schedule is None:
                raise ValueError("calendar_section_missing")
            days = schedule.get("days")
            if not isinstance(days, list) or not 1 <= len(days) <= MAX_DAYS:
                raise ValueError("calendar_days_invalid")
            seen, applicable, current_day = set(), [], None
            for day in days:
                if not isinstance(day, dict):
                    raise ValueError("calendar_day_invalid")
                day_date = instant(day.get("date")).date()
                if day_date in seen:
                    raise ValueError("calendar_day_conflict")
                seen.add(day_date)
                state, future, unknown_names = _day(day, now)
                transitions.extend(future)
                unclassified |= unknown_names
                if state != "other_day":
                    applicable.append(state)
                if day_date == now.date():
                    current_day = state
            if now.date() not in seen or not applicable:
                raise ValueError("calendar_today_missing")
            active = [value for value in applicable if value not in {"closed", "other_day"}]
            if len(active) > 1:
                raise ValueError("calendar_overlapping_days")
            selected = active[0] if active else current_day
            if selected == "other_day":
                selected = "closed"
            states.append(selected)
            result["sections"].append({"exchange": name, "state": selected})
        if "unknown" in states:
            state = "unknown"
        elif all(value == "scheduled_window" for value in states):
            state = "scheduled_window"
        elif len(set(states)) == 1:
            state = states[0]
        else:
            state = "mixed"
        return {**result, "state": state, "reason": "broker_schedule_" + state,
                "regular_price_polling_allowed": state == "scheduled_window",
                "next_transition_at": min(transitions).isoformat() if transitions else None,
                "interval_classification": "unclassified" if unclassified else "legacy_broker_window"}
    except (TypeError, ValueError, OverflowError, KeyError):
        return {**result, "state": "unknown", "reason": "calendar_incomplete_or_conflicting",
                "regular_price_polling_allowed": False}

"""Synthetic calendar contracts; no weekday assumptions or live broker calls."""
from copy import deepcopy
from datetime import datetime, timedelta, timezone

import pytest

from backend.market_schedule import polling_state, required_exchanges

NOW = datetime(2026, 10, 25, 10, tzinfo=timezone.utc)  # Sunday, deliberately.


def calendar(*, now=NOW, trading=True):
    return {"state": "available", "data": {"timezone": "UTC", "as_of": (now - timedelta(seconds=10)).isoformat(),
        "exchanges": [{"exchange": "MOEX", "days": [{"date": now.replace(hour=0).isoformat(),
            "isTradingDay": trading, "startTime": now.replace(hour=7).isoformat(),
            "endTime": now.replace(hour=16).isoformat()}]}]}}


def day(value):
    return value["data"]["exchanges"][0]["days"][0]


def observe(value, now=NOW):
    return polling_state(value, ("MOEX",), now=now)


def test_explicit_broker_sunday_opens_only_read_only_polling():
    result = observe(calendar())
    assert result["state"] == "scheduled_window"
    assert result["regular_price_polling_allowed"] is True
    assert result["main_session_verified"] is result["trade_permission"] is False
    assert result["display_timezone"] == "Europe/Moscow"


def test_broker_holiday_overrides_an_ordinary_weekday():
    monday = NOW + timedelta(days=1)
    result = observe(calendar(now=monday, trading=False), monday)
    assert result["state"] == "closed" and result["regular_price_polling_allowed"] is False


@pytest.mark.parametrize("hour, allowed", [(6, False), (7, True), (15, True), (16, False), (17, False)])
def test_half_open_session_boundaries(hour, allowed):
    now = NOW.replace(hour=hour)
    result = observe(calendar(now=now), now)
    assert result["regular_price_polling_allowed"] is allowed


@pytest.mark.parametrize("start,end,expected", [
    ("openingAuctionStartTime", "openingAuctionEndTime", "opening_auction"),
    ("closingAuctionStartTime", "closingAuctionEndTime", "closing_auction"),
    ("clearingStartTime", "clearingEndTime", "clearing"),
    ("premarketStartTime", "premarketEndTime", "premarket"),
    ("eveningStartTime", "eveningEndTime", "evening"),
])
def test_known_auction_clearing_and_extra_windows_suspend_polling(start, end, expected):
    value = calendar()
    day(value).update({start: (NOW - timedelta(minutes=1)).isoformat(), end: (NOW + timedelta(minutes=1)).isoformat()})
    result = observe(value)
    assert result["state"] == expected and result["regular_price_polling_allowed"] is False
    assert result["next_transition_at"] == (NOW + timedelta(minutes=1)).isoformat()


@pytest.mark.parametrize("age", [900, 901, -1, 86400])
def test_stale_or_future_calendar_cannot_open_polling(age):
    value = calendar()
    value["data"]["as_of"] = (NOW - timedelta(seconds=age)).isoformat()
    assert observe(value)["reason"] == "calendar_stale_or_future"


@pytest.mark.parametrize("mutation", [
    "naive", "string_bool", "missing_end", "reversed", "duplicate_day", "duplicate_exchange",
    "missing_today", "partial_clearing", "bad_interval", "missing_exchange", "wrong_timezone",
])
def test_missing_malformed_or_conflicting_evidence_stays_unknown(mutation):
    value = calendar()
    if mutation == "naive":
        day(value)["startTime"] = "2026-10-25T07:00:00"
    elif mutation == "string_bool":
        day(value)["isTradingDay"] = "false"
    elif mutation == "missing_end":
        day(value).pop("endTime")
    elif mutation == "reversed":
        day(value)["endTime"] = day(value)["startTime"]
    elif mutation == "duplicate_day":
        value["data"]["exchanges"][0]["days"].append(deepcopy(day(value)))
    elif mutation == "duplicate_exchange":
        value["data"]["exchanges"].append(deepcopy(value["data"]["exchanges"][0]))
    elif mutation == "missing_today":
        day(value)["date"] = "2026-10-26T00:00:00Z"
        day(value)["startTime"] = "2026-10-26T07:00:00Z"
        day(value)["endTime"] = "2026-10-26T16:00:00Z"
    elif mutation == "partial_clearing":
        day(value)["clearingStartTime"] = NOW.isoformat()
    elif mutation == "bad_interval":
        day(value)["intervals"] = [{"type": "unspecified", "interval": {"startTs": NOW.isoformat()}}]
    elif mutation == "missing_exchange":
        value["data"]["exchanges"][0]["exchange"] = "another-venue"
    elif mutation == "wrong_timezone":
        value["data"]["timezone"] = "Europe/Moscow"
    result = observe(value)
    assert result["state"] == "unknown" and result["regular_price_polling_allowed"] is False
    assert result["trade_permission"] is False


def test_free_form_interval_is_not_relabelled_as_main_session():
    value = calendar()
    day(value)["intervals"] = [{"type": "MAIN_OR_OTHER_UNDOCUMENTED_NAME", "interval": {
        "startTs": day(value)["startTime"], "endTs": day(value)["endTime"]}}]
    result = observe(value)
    assert result["interval_classification"] == "unclassified"
    assert result["main_session_verified"] is result["trade_permission"] is False
    day(value).pop("startTime")
    day(value).pop("endTime")
    assert observe(value)["regular_price_polling_allowed"] is False


def test_previous_utc_day_window_crosses_midnight_without_guessing_a_weekday():
    now = NOW.replace(hour=0, minute=30)
    value = calendar(now=now, trading=False)
    previous = {"date": "2026-10-24T00:00:00Z", "isTradingDay": True,
                "startTime": "2026-10-24T23:00:00Z", "endTime": "2026-10-25T01:00:00Z"}
    value["data"]["exchanges"][0]["days"].insert(0, previous)
    result = observe(value, now)
    assert result["regular_price_polling_allowed"] is True
    assert result["next_transition_at"] == "2026-10-25T01:00:00+00:00"


def test_overlapping_day_windows_are_not_silently_chosen():
    value = calendar()
    value["data"]["exchanges"][0]["days"].append({"date": "2026-10-24T00:00:00Z", "isTradingDay": True,
        "startTime": "2026-10-24T23:00:00Z", "endTime": "2026-10-25T11:00:00Z"})
    assert observe(value)["state"] == "unknown"


def test_every_required_section_must_be_present_and_in_its_window():
    value = calendar()
    other = deepcopy(value["data"]["exchanges"][0])
    other.update(exchange="MOEX-other")
    other["days"][0]["isTradingDay"] = False
    value["data"]["exchanges"].append(other)
    result = polling_state(value, ("MOEX", "MOEX-other"), now=NOW)
    assert result["state"] == "mixed" and result["regular_price_polling_allowed"] is False


@pytest.mark.parametrize("metadata", [None, {}, {"exchange": []}, {"exchange": ""}])
def test_unknown_instrument_exchange_has_no_substituted_venue(metadata):
    assert required_exchanges({"positions": [{"instrument_type": "share", "metadata": metadata}]}) == ()


def test_cash_only_bootstrap_uses_moex_but_requires_actual_schedule():
    assert required_exchanges({"positions": [{"instrument_type": "cash"}]}) == ("MOEX",)
    assert polling_state(None, ("MOEX",), now=NOW)["regular_price_polling_allowed"] is False


def test_naive_dispatch_clock_is_rejected():
    with pytest.raises(ValueError, match="aware_calendar_clock_required"):
        observe(calendar(), NOW.replace(tzinfo=None))

"""Idempotent workspace jobs with durable checkpoints and honest paid states."""
from __future__ import annotations

from contextlib import closing
from contextvars import ContextVar
from datetime import date, datetime, timezone
import json
import time
import uuid
from typing import Any, Literal

from fastapi import APIRouter, BackgroundTasks, Depends, HTTPException
from pydantic import Field

try:
    from . import app as backend
    from .ai_budget import transaction
    from .ai_jobs import AnalysisQueue
    from .monitoring_access import monitoring_connection, assert_monitoring_access_in
    from .volume_contract import HTTP_ERRORS, digest, error_code, date_range
    from .volume_state import RequestId, StrictModel, encode
except ImportError:
    import app as backend
    from ai_budget import transaction
    from ai_jobs import AnalysisQueue
    from monitoring_access import monitoring_connection, assert_monitoring_access_in
    from volume_contract import HTTP_ERRORS, digest, error_code, date_range
    from volume_state import RequestId, StrictModel, encode

router = APIRouter(prefix="/workspace", tags=["Durable workspace jobs"])
CURRENT_WORKSPACE_JOB: ContextVar[tuple[str, str, int] | None] = ContextVar("volume_current_job", default=None)
LEASE = 900
TERMINAL = {"completed", "cancelled", "failed", "uncertain"}
OWNED_JOB_SQL = "SELECT * FROM workspace_jobs WHERE id=? AND user_id=?"


class JobStopped(RuntimeError):
    code = "workspace_job_cancelled_or_lease_lost"


def initialize() -> None:
    with closing(backend.connect()) as db:
        db.executescript("""
            CREATE TABLE IF NOT EXISTS workspace_jobs (
                id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,request_id TEXT NOT NULL,
                kind TEXT NOT NULL,payload_json TEXT NOT NULL,payload_hash TEXT NOT NULL,
                state TEXT NOT NULL,stage TEXT NOT NULL,checkpoint_json TEXT NOT NULL DEFAULT '{}',
                result_json TEXT,error_code TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0,
                paid_started INTEGER NOT NULL DEFAULT 0,owner TEXT,expires_at INTEGER,
                created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
            CREATE TABLE IF NOT EXISTS workspace_job_requests (
                user_id INTEGER NOT NULL,request_id TEXT NOT NULL,job_id TEXT NOT NULL,
                payload_hash TEXT NOT NULL,PRIMARY KEY(user_id,request_id));
            CREATE INDEX IF NOT EXISTS workspace_jobs_due ON workspace_jobs(state,created_at);
            CREATE INDEX IF NOT EXISTS workspace_jobs_user ON workspace_jobs(user_id,created_at);
        """)
        db.commit()


def _iso(value: int | None) -> str | None:
    return datetime.fromtimestamp(value, timezone.utc).isoformat() if value is not None else None


def _expire(db, now: int) -> None:
    # Collection may resume from an acknowledged checkpoint. Once dispatch could
    # have occurred, restart never repeats the paid request.
    db.execute("""UPDATE workspace_jobs SET state=CASE WHEN paid_started=1 THEN 'uncertain' WHEN cancel_requested=1 THEN 'cancelled' ELSE 'queued' END,
        stage=CASE WHEN paid_started=1 THEN 'reconciliation_required' ELSE stage END,
        error_code=CASE WHEN paid_started=1 THEN 'workspace_paid_outcome_unknown' ELSE NULL END,
        owner=NULL,expires_at=NULL,updated_at=? WHERE state='running' AND expires_at<=?""", (now, now))


def _analysis_job_override(value: dict, row, db) -> None:
    result = value["result"]
    if not result or not result.get("analysis_job_id") or db is None:
        return
    child = db.execute("SELECT * FROM ai_work_jobs WHERE id=? AND user_id=?", (result["analysis_job_id"], row["user_id"])).fetchone()
    if child is None:
        return
    cancelled = child["error_code"] == "analysis_cancelled"
    cancelling = "cancel_requested_at" in child.keys() and child["cancel_requested_at"] is not None and child["status"] == "running"
    child_state = child["status"]
    if cancelled:
        child_state = "cancelled"
    elif cancelling:
        child_state = "cancel_requested"
    value.update(state=child_state, stage="done" if child["status"] == "completed" else "analysis_monitor",
                 error_code=child["error_code"], cancel_requested=cancelled or cancelling,
                 updated_at=_iso(child["updated_at"]), can_retry=False)
    if child["result_json"]:
        value["result"] = {**result, **json.loads(child["result_json"])}


def _job(row, db=None) -> dict:
    result = json.loads(row["result_json"]) if row["result_json"] else None
    value = {"job_id": row["id"], "request_id": row["request_id"], "kind": row["kind"],
             "state": "cancel_requested" if row["cancel_requested"] and row["state"] == "running" else row["state"],
             "stage": row["stage"], "created_at": _iso(row["created_at"]), "updated_at": _iso(row["updated_at"]),
             "result": result, "error_code": row["error_code"], "cancel_requested": bool(row["cancel_requested"]),
             "can_retry": row["state"] in {"failed", "cancelled"} and not row["paid_started"]}
    progress = json.loads(row["checkpoint_json"]).get("_progress")
    if progress:
        value["progress"] = progress
    if row["kind"] == "analysis":
        _analysis_job_override(value, row, db)
    return value


def get_job(user_id: int, identifier: str) -> dict:
    with transaction(backend.connect) as db:
        _expire(db, int(time.time()))
        row = db.execute(OWNED_JOB_SQL, (identifier, user_id)).fetchone()
        if row is None:
            raise HTTPException(404, "workspace_job_not_found")
        return _job(row, db)


def user_jobs(user_id: int, limit: int = 20) -> list[dict]:
    with transaction(backend.connect) as db:
        _expire(db, int(time.time()))
        rows = db.execute("SELECT * FROM workspace_jobs WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT ?", (user_id, limit)).fetchall()
        return [_job(row, db) for row in rows]


def enqueue(user_id: int, request_id: str, kind: str, payload: dict, *, before_insert=None, checkpoint: dict | None = None) -> dict:
    now = int(time.time())
    hashed = digest({"kind": kind, "payload": payload})
    with transaction(backend.connect) as db:
        _expire(db, now)
        prior = db.execute("SELECT job_id,payload_hash FROM workspace_job_requests WHERE user_id=? AND request_id=?", (user_id, request_id)).fetchone()
        if prior:
            if prior["payload_hash"] != hashed:
                raise HTTPException(409, "request_id_payload_conflict")
            return _job(db.execute("SELECT * FROM workspace_jobs WHERE id=?", (prior["job_id"],)).fetchone(), db)
        if db.execute("SELECT COUNT(*) FROM workspace_jobs WHERE user_id=? AND state IN ('queued','running')", (user_id,)).fetchone()[0] >= 5:
            raise HTTPException(429, "workspace_too_many_pending_jobs")
        identifier = uuid.uuid4().hex
        if before_insert:
            before_insert(db, identifier)
        db.execute("""INSERT INTO workspace_jobs
            (id,user_id,request_id,kind,payload_json,payload_hash,state,stage,checkpoint_json,created_at,updated_at)
            VALUES (?,?,?,?,?,?,'queued','queued',?,?,?)""",
            (identifier, user_id, request_id, kind, encode(payload), hashed, encode(checkpoint or {}), now, now))
        db.execute("INSERT INTO workspace_job_requests VALUES (?,?,?,?)", (user_id, request_id, identifier, hashed))
        return _job(db.execute("SELECT * FROM workspace_jobs WHERE id=?", (identifier,)).fetchone(), db)


def assert_current_in(db, *, allow_cancel: bool = False) -> None:
    context = CURRENT_WORKSPACE_JOB.get()
    if context is None:
        return
    identifier, owner, user_id = context
    row = db.execute("SELECT state,cancel_requested,expires_at FROM workspace_jobs WHERE id=? AND owner=? AND user_id=?", (identifier, owner, user_id)).fetchone()
    if row is None or row["state"] != "running" or row["expires_at"] <= int(time.time()) or (row["cancel_requested"] and not allow_cancel):
        raise JobStopped()
    assert_monitoring_access_in(db)


def progress(stage: str, checkpoint: dict | None = None, *, completed: int | None = None, total: int | None = None) -> None:
    context = CURRENT_WORKSPACE_JOB.get()
    if not context:
        return
    if checkpoint is not None and completed is not None:
        checkpoint["_progress"] = {"completed": completed, "total": total}
    with transaction(backend.connect) as db:
        assert_current_in(db)
        if checkpoint is not None:
            db.execute("UPDATE workspace_jobs SET stage=?,checkpoint_json=?,updated_at=?,expires_at=? WHERE id=? AND owner=?",
                       (stage, encode(checkpoint), int(time.time()), int(time.time()) + LEASE, context[0], context[1]))
        else:
            db.execute("UPDATE workspace_jobs SET stage=?,updated_at=?,expires_at=? WHERE id=? AND owner=?",
                       (stage, int(time.time()), int(time.time()) + LEASE, context[0], context[1]))


def before_model_send() -> None:
    with transaction(backend.connect) as db:
        assert_current_in(db)
        context = CURRENT_WORKSPACE_JOB.get()
        if context:
            db.execute("UPDATE workspace_jobs SET paid_started=1,stage='model_running',updated_at=? WHERE id=? AND owner=?", (int(time.time()), context[0], context[1]))


def after_model_response() -> None:
    progress("validating")


def _claim(identifier: str | None = None) -> dict | None:
    now = int(time.time())
    with transaction(backend.connect) as db:
        _expire(db, now)
        query = """SELECT * FROM workspace_jobs q WHERE q.state='queued'
            AND NOT EXISTS(SELECT 1 FROM workspace_jobs busy WHERE busy.user_id=q.user_id AND busy.state='running')""" + (" AND q.id=?" if identifier else "") + """ ORDER BY CASE WHEN q.kind='reconcile' THEN 0 ELSE MAX(1,
            CASE WHEN q.kind='events' THEN 1
                 WHEN q.kind='chat' THEN 2
                 WHEN q.kind='refresh' AND q.request_id NOT LIKE 'auto.full.%' THEN 2 ELSE 3 END
            - CAST(MAX(0, ? - q.created_at) / 300 AS INTEGER)) END, q.created_at,q.id LIMIT 1"""
        # Each five minutes of waiting promotes one level. Even catalogue/full
        # work eventually reaches the front; existing per-user leases still win.
        row = db.execute(query, ((identifier,) if identifier else ()) + (now,)).fetchone()
        if not row:
            return None
        owner = uuid.uuid4().hex
        # One collecting/model worker per user; independent users remain eligible.
        if db.execute("SELECT 1 FROM workspace_jobs WHERE user_id=? AND state='running'", (row["user_id"],)).fetchone():
            return None
        db.execute("UPDATE workspace_jobs SET state='running',owner=?,expires_at=?,updated_at=? WHERE id=?", (owner, now + LEASE, now, row["id"]))
        return {**dict(row), "owner": owner}


def _enqueue_analysis(job: dict) -> dict:
    progress("analysis_queued")
    with transaction(backend.connect) as db:
        assert_current_in(db)
        result = {"analysis_job_id": AnalysisQueue(backend.connect).enqueue_in(db, job["user_id"])["job_id"]}
        try:
            from .background_dispatch import mark_manual_in
        except ImportError:
            from background_dispatch import mark_manual_in
        mark_manual_in(db, job["user_id"], result["analysis_job_id"])
        db.execute("UPDATE workspace_jobs SET result_json=? WHERE id=? AND owner=?", (encode(result), job["id"], job["owner"]))
    return result


def _perform_job(job: dict, user: Any, payload: dict, checkpoint: dict) -> dict:
    try:
        from .volume_workspace import collect
        from .volume_chat import run_message
        from .volume_plans import reconcile_plan
    except ImportError:
        from volume_workspace import collect
        from volume_chat import run_message
        from volume_plans import reconcile_plan
    if job["kind"] == "events":
        try:
            from .event_monitor import collect_events
        except ImportError:
            from event_monitor import collect_events
        return collect_events(user, payload, checkpoint, progress)
    if job["kind"] == "refresh":
        if job["request_id"].startswith("auto.full."):
            try:
                from .background_dispatch import automatic_collection_gate
            except ImportError:
                from background_dispatch import automatic_collection_gate
            waiting = automatic_collection_gate(user, payload, checkpoint)
            if waiting is not None:
                return waiting
        return collect(user, payload, checkpoint, progress)
    if job["kind"] == "chat":
        return run_message(user, job, payload)
    if job["kind"] == "analysis":
        return _enqueue_analysis(job)
    if job["kind"] == "reconcile":
        return reconcile_plan(user, payload, progress)
    raise HTTPException(422, "workspace_job_kind_invalid")


def _failure_state(row, error: Exception, pending_money) -> tuple[str, str]:
    if row["paid_started"] and pending_money:
        return "uncertain", "workspace_paid_outcome_unknown"
    if row["cancel_requested"] or isinstance(error, JobStopped):
        return "cancelled", "workspace_job_cancelled"
    return "failed", error_code(error)


def _fail_job(job: dict, error: Exception) -> None:
    # Paid outcome may be settled even when model JSON is invalid. The job is
    # still not replayable; a new intentional message is a new operation.
    with transaction(backend.connect) as db:
        row = db.execute("SELECT * FROM workspace_jobs WHERE id=? AND owner=? AND state='running'", (job["id"], job["owner"])).fetchone()
        if row is None:
            return
        pending_money = db.execute("SELECT 1 FROM ai_money_reservations WHERE user_id=? AND state IN ('reserved','uncertain') AND created_at>=?", (job["user_id"], row["created_at"])).fetchone()
        status, code = _failure_state(row, error, pending_money)
        db.execute("UPDATE workspace_jobs SET state=?,error_code=?,updated_at=? WHERE id=? AND owner=?", (status, code, int(time.time()), job["id"], job["owner"]))


def run_job(identifier: str | None = None) -> None:
    job = _claim(identifier)
    if job is None:
        return
    token = CURRENT_WORKSPACE_JOB.set((job["id"], job["owner"], job["user_id"]))
    try:
        with closing(backend.connect()) as db:
            user = db.execute("SELECT * FROM users WHERE id=?", (job["user_id"],)).fetchone()
        if user is None or not user["tinvest_token_encrypted"]:
            raise HTTPException(409, "tinvest_not_connected")
        payload, checkpoint = json.loads(job["payload_json"]), json.loads(job["checkpoint_json"])
        with monitoring_connection(job["user_id"], user["tinvest_token_encrypted"]):
            result = _perform_job(job, user, payload, checkpoint)
            with transaction(backend.connect) as db:
                assert_current_in(db)
                db.execute("UPDATE workspace_jobs SET state='completed',stage='done',result_json=?,checkpoint_json='{}',updated_at=? WHERE id=? AND owner=?", (encode(result), int(time.time()), job["id"], job["owner"]))
    except Exception as error:
        _fail_job(job, error)
    finally:
        CURRENT_WORKSPACE_JOB.reset(token)


def drain(limit: int = 5) -> None:
    # A restart can leave only expired running rows. Recover those leases before
    # checking for queued work, even when no client is polling the workspace.
    with transaction(backend.connect) as db:
        _expire(db, int(time.time()))
    for _ in range(limit):
        with closing(backend.connect()) as db:
            row = db.execute("SELECT id FROM workspace_jobs WHERE state='queued' ORDER BY created_at,id LIMIT 1").fetchone()
        if row is None:
            return
        run_job()


class Refresh(RequestId):
    currency: Literal["RUB", "USD", "EUR"] = "RUB"
    start: date | None = None
    end: date | None = None


class AnalysisRequest(RequestId):
    reason: Literal["manual"] = "manual"


@router.post("/refresh", status_code=202, responses=HTTP_ERRORS)
